mapper.insert:
INSERT IGNORE INTO saved_support_program (account_id, support_program_id, saved_at)
SELECT #{accountId}, program.id, #{savedAt}
FROM support_program program
WHERE program.source_code = #{sourceCode}
  AND program.source_program_id = #{sourceProgramId}
  AND program.is_source_present = TRUE

mapper.delete:
DELETE saved
FROM saved_support_program saved
JOIN support_program program ON program.id = saved.support_program_id
WHERE saved.account_id = #{accountId}
  AND program.source_code = #{sourceCode}
  AND program.source_program_id = #{sourceProgramId}

mapper.select:
SELECT

FROM saved_support_program saved
JOIN support_program program ON program.id = saved.support_program_id
WHERE saved.account_id = #{accountId}
  AND program.source_code = #{sourceCode}
  AND program.source_program_id = #{sourceProgramId}
  AND program.is_source_present = TRUE
